.target sm_120
.address_size 64

.visible .entry matmul_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    // ------------------------------
    // Thread/block indices
    // ------------------------------
    .reg .u32   %tid_x, %tid_y;
    .reg .u32   %bid_x, %bid_y;
    .reg .u32   %ntid_x, %ntid_y;
    .reg .u32   %block_dim_x, %block_dim_y;

