    mov.u32 %tid_y, %tid.y;
    mov.u32 %bid_x, %ctaid.x;
    mov.u32 %bid_y, %ctaid.y;
    mov.u32 %ntid_x, %ntid.x;          // should be 16
    mov.u32 %ntid_y, %ntid.y;          // should be 16

    // ------------------------------
    // Compute global row / column
    // ------------------------------
    .reg .u32   %row, %col;
    mad.lo.u32 %row, %bid_y, %ntid_y, %tid_y;   // row = blockIdx.y * 16 + threadIdx.y
    mad.lo.u32 %col, %bid_x, %ntid_x, %tid_x;   // col = blockIdx.x * 16 + threadIdx.x

    // ------------------------------
    // Load kernel arguments
    // ------------------------------
    .reg .u64   %A, %B, %C;
    .reg .u32   %N;
    ld.param.u64 %A, [A_ptr];
    ld.param.u64 %B, [B_ptr];
    ld.param.u64 %C, [C_ptr];
    ld.param.u32 %N, [N];

    // ------------------------------
    // Allocate shared memory for tiles (16x16 each)
    // ------------------------------
    .shared .align 4 .b16 As[256];
    .shared .align 4 .b16 Bs[256];

    // ------------------------------
    // Accumulator in fp32
    // ------------------------------
    .reg .f32   %acc;
    mov.f32 %acc, 0f0;

    // ------------------------------
    // Loop over K dimension in tiles of 16
    // ------------------------------
    .reg .u32   %t;
    mov.u32 %t, 0;

