    // break condition
    setp.ge.u32 %p0, %t, %N;
    @%p0 bra END_LOOP;

    // -------------------------------------------------
    // Load A tile into shared memory (As)
    // -------------------------------------------------
    .reg .u32   %a_row, %a_col, %a_idx;
    .reg .u64   %a_addr;
    .reg .b16   %a_val;

    // a_row = %row
    // a_col = %t + %tid_x
    add.u32 %a_col, %t, %tid_x;
    setp.ge.u32 %p1, %a_col, %N;           // out-of-bounds?
    @%p1 mov.b16 %a_val, 0;               // zero if OOB
    @!%p1 {
