        mul.lo.u32 %a_idx, %row, %N;
        add.u32 %a_idx, %a_idx, %a_col;
        // address = %A + (index * 2)
        mul.wide.u32 %a_addr, %a_idx, 2;
        add.u64 %a_addr, %A, %a_addr;
        ld.global.b16 %a_val, [%a_addr];
