    // Load B tile into shared memory (Bs)
    // -------------------------------------------------
    .reg .u32   %b_row, %b_col, %b_idx;
    .reg .u64   %b_addr;
    .reg .b16   %b_val;

    // b_row = %t + %tid_y
    // b_col = %col
    add.u32 %b_row, %t, %tid_y;
    setp.ge.u32 %p2, %b_row, %N;
    @%p2 mov.b16 %b_val, 0;
    @!%p2 {
