        add.u32 %b_idx, %b_idx, %col;
        mul.wide.u32 %b_addr, %b_idx, 2;
        add.u64 %b_addr, %B, %b_addr;
        ld.global.b16 %b_val, [%b_addr];
    }
    // store into shared memory
    mul.lo.u32 %b_idx, %tid_y, 16;
    add.u32 %b_idx, %b_idx, %tid_x;
    st.shared.b16 [Bs+%b_idx*2], %b_val;

    // -------------------------------------------------
    // Synchronize threads before computation
    // -------------------------------------------------
    bar.sync 0;

    // -------------------------------------------------
    // Compute partial dot product for this tile
    // -------------------------------------------------
    .reg .s32   %k;
    mov.s32 %k, 0;
DOT_LOOP:
    setp.ge.s32 %p3, %k, 16;
    @%p3 bra END_DOT;

    // load A element from shared memory
    mul.lo.u32 %a_idx, %tid_y, 16;
    add.u32 %a_idx, %a_idx, %k;            // As[tid_y][k]
    ld.shared.b16 %a_val, [As+%a_idx*2];
    cvt.rn.f32.f16 %f32_a, %a_val;

    // load B element from shared memory
    mul.lo.u32 %b_idx, %k, 16;
    add.u32 %b_idx, %b_idx, %tid_x;        // Bs[k][tid_x]
    ld.shared.b16 %b_val, [Bs+%b_idx*2];
    cvt.rn.f32.f16 %f32_b, %b_val;

