    // -------------------------------------------------
    setp.ge.u32 %p4, %row, %N;
    setp.ge.u32 %p5, %col, %N;
    or.pred %p6, %p4, %p5;
    @%p6 bra END_WRITE;   // out of bounds, skip write

    // convert acc (fp32) to fp16
    cvt.rn.f16.f32 %a_val, %acc;

    // compute C address
    mul.lo.u32 %a_idx, %row, %N;
    add.u32 %a_idx, %a_idx, %col;
    mul.wide.u32 %a_addr, %a_idx, 2;
    add.u64 %a_addr, %C, %a_addr;
    st.global.b16 [%a_addr], %a_val;

