.target sm_120
.address_size 64

.visible .entry matmul_fp16(
    .param .u64 A,
    .param .u64 B,
    .param .u64 C,
    .param .u32 N
)
{
    // registers
    .reg .u64 %a_ptr, %b_ptr, %c_ptr, %addr;
    .reg .u32 %n, %tile, %tid_x, %tid_y, %block_x, %block_y;
    .reg .u32 %row, %col, %k, %a_col, %b_row, %i, %s;
    .reg .f16 %a_f16, %b_f16, %c_f16;
    .reg .f32 %a_f32, %b_f32, %sum;
    .reg .pred %p;

    // shared memory tiles (16x16 = 256 fp16 elements each)
    .shared .align 2 .b16 As[256];
    .shared .align 2 .b16 Bs[256];

    // load kernel parameters
    ld.param.u64 %a_ptr, [A];
    ld.param.u64 %b_ptr, [B];
    ld.param.u64 %c_ptr, [C];
    ld.param.u32 %n,     [N];

    mov.u32 %tile, 16;

    // thread / block indices
    mov.u32 %tid_x,   %tid.x;
    mov.u32 %tid_y,   %tid.y;
    mov.u32 %block_x, %ctaid.x;
    mov.u32 %block_y, %ctaid.y;

    // global row / column for the output element this thread will compute
    mad.lo.u32 %row, %block_y, %tile, %tid_y;
    mad.lo.u32 %col, %block_x, %tile, %tid_x;

    // accumulator in fp32
    mov.f32 %sum, 0f0;

    // tile loop over K dimension
    mov.u32 %k, 0;

LOOP_K:
    // column index within A for this tile
    mad.lo.u32 %a_col, %k, %tile, %tid_x;   // a_col = k*tile + tid_x
    // row index within B for this tile
    mad.lo.u32 %b_row, %k, %tile, %tid_y;   // b_row = k*tile + tid_y

    // -------- load A element --------
    mul.wide.u32 %addr, %row, %n;           // row * N
    add.u32 %addr, %addr, %a_col;           // + col within tile
    mul.wide.u32 %addr, %addr, 2;           // * sizeof(fp16)
    add.u64 %addr, %a_ptr, %addr;
    ld.global.f16 %a_f16, [%addr];

    // store into shared As
    mad.lo.u32 %i, %tid_y, %tile, %tid_x;   // i = tid_y*tile + tid_x
    mul.wide.u32 %i, %i, 2;
    st.shared.f16 [As+%i], %a_f16;

    // -------- load B element --------
    mul.wide.u32 %addr, %b_row, %n;         // b_row * N
    add.u32 %addr, %addr, %col;             // + global column
    mul.wide.u32 %addr, %addr, 2;
    add.u64 %addr, %b_ptr, %addr;
    ld.global.f16 %b_f16, [%addr];

    // store into shared Bs (same shared index %i)
    st.shared.f16 [Bs+%i], %b_f16;

    // synchronize to make sure the tile is fully loaded
    bar.sync 0;

    // -------- compute partial product for this tile --------
    mov.u32 %s, 0;
INNER_LOOP:
    // A tile value: As[tid_y * tile + s]
    mad.lo.u32 %i, %tid_y, %tile, %s;
    mul.wide.u32 %i, %i, 2;
    ld.shared.f16 %a_f16, [As+%i];
    cvt.f32.f16 %a_f32, %a_f16;

    // B tile value: Bs[s * tile + tid_x]
    mad.lo.u32 %i, %s, %tile, %tid_x;
    mul.wide.u32 %i, %i, 2;
    ld.shared.f16 %b_f16, [Bs+%i];
    cvt.f32.f16 %b_f32, %b_f16;

    // multiply‑accumulate
    fma.rn.f32 %sum, %a_f32, %b_f32, %sum;

    // loop over s
    add.u32 %s, %s, 1;
    setp.lt.u32 %p, %s, %tile;
    @%p bra INNER_LOOP;

    // synchronize before loading next tile
    bar.sync 0;

    // advance to next K‑tile
    add.u32 %k, %k, 1;
    mul.lo.u32 %i, %k, %tile;               // i = k*tile
    setp.lt.u32 %p, %i, %n;
    @%p bra LOOP_K;

WRITE_RESULT:
    // bounds check (in case N is not a multiple of tile)
    setp.ge.u32 %p, %row, %n;
    @%p bra END;
    setp.ge.u32 %p, %col, %n;
    @%p bra END;

    // address of C[row, col]
    mul.wide.u32 %addr, %row, %n;
    add.u32 %addr, %addr, %col;
    mul.wide.u32 %addr, %addr, 2;
    add.u64 %addr, %c_ptr, %addr;

    // write result as fp16
    cvt.f16.f32 %c_f16, %sum;
    st.global.f16 [%addr], %c_f16;

END:
    ret;
}
