    //--- load kernel parameters --------------------------------------------
    ld.param.u64    %A, [A_ptr];
    ld.param.u64    %B, [B_ptr];
    ld.param.u64    %C, [C_ptr];
    ld.param.u32    %tmp32, [N];
    cvt.u64.u32     %tmp64, %tmp32;        // N as 64‑bit for address math

    //--- thread / block indices --------------------------------------------
    mov.u32 %tid_x, %tid.x;
    mov.u32 %tid_y, %tid.y;
    mov.u32 %blk_x, %ctaid.x;
    mov.u32 %blk_y, %ctaid.y;

    // row = blockY * 16 + tid_y
    mad.lo.s32 %row, %blk_y, 16, %tid_y;
    // col = blockX * 16 + tid_x
    mad.lo.s32 %col, %blk_x, 16, %tid_x;

    //--- bounds check -------------------------------------------------------
    setp.ge.s32 %p, %row, %tmp32;
    @%p bra DONE;
    setp.ge.s32 %p, %col, %tmp32;
    @%p bra DONE;

    //--- initialize accumulator ---------------------------------------------
    mov.f32 %sum, 0f0;

    //--- main K loop --------------------------------------------------------
    mov.s32 %k, 0;
K_LOOP:
    setp.ge.s32 %p, %k, %tmp32;
    @%p bra K_DONE;

    // A[row, k] address
    // offset = (row * N + k) * 2
    mul.wide.s32 %tmp64, %row, %tmp32;        // row * N
    add.s32      %tmp32, %tmp64, %k;          // row*N + k (still 32‑bit)
    mul.wide.s32 %addr, %tmp32, 2;           // * sizeof(fp16)
    add.u64      %addr, %A, %addr;
    ld.global.f16 %a_val, [%addr];

    // B[k, col] address
    // offset = (k * N + col) * 2
    mul.wide.s32 %tmp64, %k, %tmp32;          // k * N
    add.s32      %tmp32, %tmp64, %col;        // k*N + col
    mul.wide.s32 %addr, %tmp32, 2;
    add.u64      %addr, %B, %addr;
    ld.global.f16 %b_val, [%addr];

    // convert to fp32
    cvt.f32.f16 %a_f32, %a_val;
    cvt.f32.f16 %b_f32, %b_val;

    // fma
    fma.rn.f32 %sum, %a_f32, %b_f32, %sum;

    // k++
    add.s32 %k, %k, 1;
    bra K_LOOP;
K_DONE:

    //--- write result -------------------------------------------------------
    // C[row, col] address
    // offset = (row * N + col) * 2
    mul.wide.s32 %tmp64, %row, %tmp32;        // row * N
    add.s32      %tmp32, %tmp64, %col;        // row*N + col
    mul.wide.s32 %addr, %tmp32, 2;
    add.u64      %addr, %C, %addr;

    // convert back to fp16
    cvt.f16.f32 %c_val, %sum;
    st.global.f16 [%addr], %c_val;

DONE:
    ret;
}
'''

# -------------------------------------------------------------------------
# PyTorch wrapper that uses the PTX kernel
import torch
import torch.nn as nn

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        # ptx_load / ptx_launch are provided by the harness
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        N = A.shape[0]
        C = torch.empty_like(A, dtype=torch.float16, device=A.device)

        grid  = ((N + 15) // 16, (N + 15) // 16, 1)
        block = (16, 16, 1)

        # arguments: pointers (as 64‑bit integers) and size N (as 32‑bit)
        args = [A.data_ptr(), B.data_ptr(), C.data_ptr(), N]

        ptx_launch(self.module, "matmul_kernel", grid, block, args)
        return C

# PTX source for fp16 matrix multiplication (C = A @ B)
PTX_SOURCE = r'''
.version 7.3
.target sm_120
.address_size 64

.visible .entry kernel_matmul(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    // Thread indices
    .reg .u32   %tid_x, %tid_y;
    .reg .u32   %cta_x, %cta_y;
    .reg .u32   %blockDim_x, %blockDim_y;
    .reg .u32   %row, %col;

    // Loop index and size
    .reg .u32   %k;
    .reg .u32   %N;

    // Pointers and offsets
    .reg .u64   %A, %B, %C;
    .reg .u64   %addrA, %addrB, %addrC;
    .reg .u64   %tmp64;

    // Values
    .reg .f16   %a_half, %b_half;
    .reg .f32   %a_f32, %b_f32, %sum;

    // Load parameters
    ld.param.u64    %A, [A_ptr];
    ld.param.u64    %B, [B_ptr];
    ld.param.u64    %C, [C_ptr];
    ld.param.u32    %N, [N];

    // Built‑in variables
    mov.u32         %tid_x,   %tid.x;
    mov.u32         %tid_y,   %tid.y;
    mov.u32         %cta_x,   %ctaid.x;
    mov.u32         %cta_y,   %ctaid.y;
    mov.u32         %blockDim_x, %ntid.x;
    mov.u32         %blockDim_y, %ntid.y;

    // Compute global row and column
    mad.lo.u32      %row, %cta_y, %blockDim_y, %tid_y;   // row = blockIdx.y * blockDim.y + threadIdx.y
    mad.lo.u32      %col, %cta_x, %blockDim_x, %tid_x;   // col = blockIdx.x * blockDim.x + threadIdx.x

    // Guard against out‑of‑bounds
    setp.ge.u32     %p0, %row, %N;
    setp.ge.u32     %p1, %col, %N;
    @%p0 bra        DONE;
    @%p1 bra        DONE;

    // Initialize accumulator
    mov.f32         %sum, 0.0;

    // Compute base address for this row in A: A + (row * N) * 2
    mul.lo.u64      %tmp64, %row, %N;          // row * N
    mul.lo.u64      %tmp64, %tmp64, 2;        // * sizeof(half)
    add.u64         %addrA, %A, %tmp64;       // A_base

    // Compute base address for this column in B: B + col * 2
    mul.lo.u64      %tmp64, %col, 2;
    add.u64         %addrB, %B, %tmp64;       // B_base (will add k* N *2 each loop)

    // Loop over k
    mov.u32         %k, 0;
LOOP:
    setp.ge.u32     %p2, %k, %N;
    @%p2 bra        END_LOOP;

    // Load A[row, k]
    mul.lo.u64      %tmp64, %k, 2;            // k * sizeof(half)
    add.u64         %tmp64, %addrA, %tmp64;   // addrA + k*2
    ld.global.f16   %a_half, [%tmp64];
    cvt.f32.f16     %a_f32, %a_half;

    // Load B[k, col]
    // B address = B + (k * N + col) * 2
    mul.lo.u64      %tmp64, %k, %N;           // k * N
    mul.lo.u64      %tmp64, %tmp64, 2;        // *2
    add.u64         %tmp64, %tmp64, %addrB;   // + col*2 already in addrB
    ld.global.f16   %b_half, [%tmp64];
    cvt.f32.f16     %b_f32, %b_half;

    // Accumulate
    fma.rn.f32      %sum, %a_f32, %b_f32, %sum;

    // k++
    add.u32         %k, %k, 1;
    bra.uni         LOOP;

END_LOOP:
    // Convert sum to half and store to C
    cvt.rn.f16.f32  %a_half, %sum;          // reuse %a_half as output half
    // Compute address C[row, col] = C + ((row * N) + col) * 2
    mul.lo.u64      %tmp64, %row, %N;       // row * N
    add.u64         %tmp64, %tmp64, %col;   // row*N + col
    mul.lo.u64      %tmp64, %tmp64, 2;
    add.u64         %addrC, %C, %tmp64;
    st.global.f16   [%addrC], %a_half;

DONE:
    ret;
}
'''

# --------------------------------------------------------------
# Python wrapper class using the provided PTX harness
# --------------------------------------------------------------
import torch
from ptx_harness import ptx_load, ptx_launch  # assumed provided by the harness

class ModelNew:
    def __init__(self):
        # Load the PTX module once
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Executes C = A @ B where A, B, C are fp16 tensors.
        """
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        N = A.shape[0]
        assert A.shape == (N, N) and B.shape == (N, N)

        C = torch.empty_like(A)

        # Launch configuration (16x16 thread block)
        block = (16, 16, 1)
        grid = ((N + block[0] - 1) // block[0],
                (N + block[1] - 1) // block[1],
                1)

        # Arguments: raw device pointers and size
        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            N
        ]

        ptx_launch(self.module, "kernel_matmul", grid, block, args)
        return C
